{"type": "run_bash", "command": "cat > /app/compute.py << 'EOF'
import csv, json
from collections import defaultdict

# reference tc per run
ref = {}
with open('/app/data/boards.csv') as f:
    for row in csv.DictReader(f):
        if row['role']=='reference':
            ref[row['run_id']] = row['tc_id']

# units
unit = {}
runs = []
with open('/app/data/runs.csv') as f:
    for row in csv.DictReader(f):
        unit[row['run_id']] = row['temp_unit']
        runs.append(row)

# group temp data
data = defaultdict(list)
with open('/app/data/thermocouples.csv') as f:
    for row in csv.DictReader(f):
        data[row['run_id']].append(row)

# convert to C
def to_c(r):
    t=float(r['temp'])
    if unit.get(r['run_id'],'C')=='F':
        t=(t-32)*5/9
    return t

def compute(rid):
    tc = ref.get(rid)
    rows = data.get(rid, [])
    if not tc or not rows:
        return {'tc_id': tc, 'max_preheat_ramp': None, 'tal_s': None, 'peak_c': None, 'status':'non-compliant'}
    # filter to reference tc
    pts = sorted([(float(r['t_s']), to_c(r)) for r in rows if r['tc_id']==tc])
    if not pts:
        return {'tc_id': tc, 'max_preheat_ramp': None, 'tal_s': None, 'peak_c': None, 'status':'non-compliant'}
    # peak
    peak = max(t for _,t in pts)
    # preheat ramp: max over consecutive pairs both in [60,160]
    maxramp = None
    for i in range(1,len(pts)):
        t0,v0 = pts[i-1]; t1,v1 = pts[i]
        if 60<=v0<=160 and 60<=v1<=160:
            dt = t1-t0
            r = abs(v1-v0)/dt if dt>0 else 0
            if maxramp is None or r>maxramp:
                maxramp = r
    # TAL: time at or above liquidus 227, interpolate at crossing
    L=227
    tal=0.0
    for i in range(1,len(pts)):
        t0,v0=pts[i-1]; t1,v1=pts[i]
        if v0>=L and v1>=L:
            tal += (t1-t0)
        elif v0<L and v1>=L:
            # crossing upward: time from interpolated point to t1
            fc = (L-v0)/(v1-v0)
            tal += (t1-t0)*(1-fc)
        elif v0>=L and v1<L:
            fc = (L-v0)/(v1-v0)  # fraction from t0 where it crosses down
            tal += (t1-t0)*fc
        # else below
    # status
    failing = False
    if maxramp is None or maxramp>1.5:
        failing=True
    if tal<45 or tal>90:
        failing=True
    if peak<252:
        failing=True
    return {'tc_id':tc,'max_preheat_ramp':round(maxramp,2) if maxramp is not None else None,
            'tal_s':round(tal,2),'peak_c':round(peak,2),
            'status':'non-compliant' if failing else 'compliant'}

out = {'ramp_limit_c_per_s':1.5,'runs':{},'failing_runs':[]}
for r in runs:
    rid=r['run_id']
    out['runs'][rid]=compute(rid)
    if out['runs'][rid]['status']=='non-compliant':
        out['failing_runs'].append(rid)
out['failing_runs']=sorted(out['failing_runs'])
json.dump(out, open('/app/output/reflow_report.json','w'), indent=2)
print(json.dumps(out, indent=2))
EOF
