import csv, json, math
from collections import defaultdict

runs = {}
with open('/app/data/runs.csv') as f:
    for r in csv.DictReader(f):
        runs[r['run_id']] = r

# load thermocouple data per (run,tc)
data = defaultdict(list)  # key -> list of (t, temp_c)
with open('/app/data/thermocouples.csv') as f:
    for r in csv.DictReader(f):
        unit = runs[r['run_id']]['temp_unit']
        t = float(r['t_s']); temp = float(r['temp'])
        if unit == 'F':
            temp = (temp - 32) * 5.0/9.0
        data[(r['run_id'], r['tc_id'])].append((t, temp))

LIQ = 227.0
report = {"ramp_limit_c_per_s": 2.5, "runs": {}, "failing_runs": []}

for run_id in sorted(runs):
    tcs = sorted(set(tc for (rn, tc) in data if rn == run_id))
    if not tcs:
        report['runs'][run_id] = {"tc_id": None, "max_preheat_ramp": None, "tal_s": None, "peak_c": None, "status": "non-compliant"}
        report['failing_runs'].append(run_id)
        continue
    # coldest tc = lowest peak
    peaks = {tc: max(t for (t, _) in data[(run_id, tc)]) for tc in tcs}
    tc = min(peaks, key=lambda x: peaks[x])
    pts = sorted(data[(run_id, tc)], key=lambda x: x[0])
    temps = [p[1] for p in pts]; ts = [p[0] for p in pts]
    peak = max(temps)
    # preheat ramp: steps where both samples in [60,160]
    maxramp = 0.0
    for i in range(len(pts)-1):
        t0, v0 = pts[i]; t1, v1 = pts[i+1]
        if 60 <= v0 <= 160 and 60 <= v1 <= 160:
            dt = t1 - t0
            if dt > 0:
                ramp = abs(v1 - v0)/dt
                if ramp > maxramp: maxramp = ramp
    # TAL: seconds at or above liquidus, interpolate at crossings
    tal = 0.0
    for i in range(len(pts)-1):
        t0, v0 = pts[i]; t1, v1 = pts[i+1]
        dt = t1 - t0
        if v0 >= LIQ and v1 >= LIQ:
            tal += dt
        elif v0 < LIQ and v1 >= LIQ:
            frac = (LIQ - v0)/(v1 - v0); tal += dt*(1-frac)
        elif v0 >= LIQ and v1 < LIQ:
            frac = (LIQ - v0)/(v1 - v0); tal += dt*(1-frac)
    ramp = round(maxramp, 2); tal = round(tal, 2); pk = round(peak, 2)
    status = "compliant"
    if maxramp > 2.5 or tal < 30 or tal > 75 or peak < 252:
        status = "non-compliant"
    report['runs'][run_id] = {"tc_id": tc, "max_preheat_ramp": ramp, "tal_s": tal, "peak_c": pk, "status": status}
    if status == "non-compliant":
        report['failing_runs'].append(run_id)

report['failing_runs'] = sorted(report['failing_runs'])
with open('/app/output/reflow_report.json', 'w') as f:
    json.dump(report, f, indent=2)
print(json.dumps(report, indent=2))
