    ivs = [iv for iv in down.get(m, []) if iv[0] >= start and iv[0] < end]  # rows are minute-start; keep minutes whose start is in [14:00,22:00)
    # exclude micro-stops: consecutive DOWN minutes < 3 form a micro-stop
    ivs.sort()
    # group consecutive minutes into contiguous blocks
    blocks = []
    for s,e in ivs:
        if blocks and s == blocks[-1][1]:
            blocks[-1] = (blocks[-1][0], e)
        else:
            blocks.append((s,e))
    total = 0
    for s,e in blocks:
        mins = int((e-s).total_seconds()//60)
        if mins >= 3:
            total += mins
    result[m] = total
    if total > limit:
        over.append(m)

out = {'limit_min': limit, 'downtime_by_machine': result, 'over_limit': sorted(over)}
